head.script:
scwin.onpageload = function() {
    //1.autoComplete에
    //noResult:useData 로 설정했을 때
    //새로운 값을 setValue시 값 저장 및 표현 안됨

    //autoComplete에 값 설정
	auto1.setValue("abc");
    //autoComplete 값 확인
    console.log("auto1.getValue(): "+ auto1.getValue());
    window.checkLog1 = auto1.getValue();

    //2.autoComplete에
    //noResult:useData 로 설정하고
    //데이터리스트의 컬럼을 ref로 설정한 뒤
    //데이터리스트 컬럼 값을 바꾸었을 때 표현 안됨

    //행추가 및 값 설정
    dataList1.insertRow(0);
    dataList1.setRowPosition(0);
    dataList1.setCellData(0, "col1", "abc");

    //데이터리스트 값 확인
    console.log("dataList1.getAllJSON(): "+ JSON.stringify(dataList1.getAllJSON()));
    //autoComplete 값 확인
    console.log("auto2.getValue(): "+ auto2.getValue());
    window.checkLog2 = auto2.getValue();

    //3.autoComplete에
    //noResult:useData 로 설정하고
    //맵을 ref로 설정한 뒤
    //맵 값을 바꾸었을 때 표현 안됨

    //key1 에 abc를 설정
    dataMap1.set("key1", "abc");

    //dataMap1 값 확인
    console.log("dataMap1.get('key1') : " + dataMap1.get("key1"));
    //autoComplete 값 확인
    console.log("auto3.getValue() : " + auto3.getValue());
    window.checkLog3 = auto3.getValue();

}

	scwin.checkVal1 = function() {
		const checkVal1 = window.checkLog1 == 'abc';
		const checkVal2 = window.checkLog2 == 'abc';
		const checkVal3 = window.checkLog3 == 'abc';		
		return checkVal1 && checkVal2 && checkVal3;
	}
	scwin.checkVal2 = function() {
		const checkVal1 = WebSquare.wUnit.getDomById('auto1_label').innerText == 'abc';
		const checkVal2 = WebSquare.wUnit.getDomById('auto2_label').innerText == 'abc';
		const checkVal3 = WebSquare.wUnit.getDomById('auto3_label').innerText == 'abc';
		return checkVal1 && checkVal2 && checkVal3;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
